ForeverCompanionDungeonReference=R
local M,L=ForeverCompanionBossMechanics,ForeverCompanionLoot
local function key(s)
 if type(s)~='string' then return '' end
 return s:lower():gsub('%s*%(rare%)',''):gsub('%s*%(summoned%)',''):gsub('%s*%(event%)',''):gsub('[^%w]','')
end
function R.Canonical(d,b)
 if type(b)~='string' then return b end
 local stripped=b:gsub('%s*%([Rr]are%)',''):gsub('%s*%([Ss]ummoned%)',''):gsub('%s*%([Ee]vent%)','')
 for alias,name in pairs(R.aliases) do if key(alias)==key(stripped) then stripped=name;break end end
 for name in pairs(M.data[d] or {}) do if key(name)==key(stripped) then return name end end
 return stripped
end
M.Canonical=R.Canonical
-- Collapse only documented aliases inside the same dungeon, never between wings.
for d,records in pairs(M.data) do
 local names={};for name in pairs(records) do names[#names+1]=name end
 for _,name in ipairs(names) do
  local canonical=R.Canonical(d,name)
  if canonical~=name then records[canonical]=records[canonical] or records[name];records[name]=nil end
 end
end
for _,r in ipairs(R.encounters) do
 r.boss=R.Canonical(r.dungeon,r.boss)
 M.data[r.dungeon]=M.data[r.dungeon] or {}
 local previous=M.Get(r.dungeon,r.boss)
 if r.state~='pending' or not previous then M.data[r.dungeon][r.boss]=r
 elseif not previous.state then previous.state=#previous.mechanics>0 and 'documented' or 'none' end
end
R.conflicts={}
local seen={}
for _,r in ipairs(L.records) do
 r.boss=R.Canonical(r.dungeon,r.boss)
 seen[r.dungeon..'\031'..r.boss..'\031'..r.item:lower()]=r
end
L.InvalidateBossIndex()
for _,r in ipairs(R.loot) do
 r.boss=R.Canonical(r.dungeon,r.boss)
 local identity=r.dungeon..'\031'..r.boss..'\031'..r.item:lower()
 local previous=seen[identity]
 if previous then
  if previous.itemID and r.itemID and previous.itemID~=r.itemID then
   R.conflicts[#R.conflicts+1]={dungeon=r.dungeon,boss=r.boss,item=r.item,retained=previous.itemID,alternative=r.itemID,source=r.source}
  end
 else
  local added=L.Add(r);if added then seen[identity]=r end
 end
end
-- Add explicit guide states for source labels already present in older imports.
for _,r in ipairs(L.records) do
 M.data[r.dungeon]=M.data[r.dungeon] or {}
 if not M.Get(r.dungeon,r.boss) then
  M.data[r.dungeon][r.boss]={mechanics={},state=r.boss=='Trash Drops' and 'not-boss' or 'pending',source=r.encounterSource or r.source,reviewed=R.reviewed}
 end
end
function R.Coverage(d)
 local c={bosses=0,documented=0,none=0,pending=0,loot=0,unknownIDs=0}
 for _,r in pairs(M.data[d] or {}) do
  if r.state~='not-boss' then
   c.bosses=c.bosses+1
   if #r.mechanics>0 then c.documented=c.documented+1
   elseif r.state=='pending' then c.pending=c.pending+1 else c.none=c.none+1 end
  end
 end
 for _,r in ipairs(L.records) do if r.dungeon==d then c.loot=c.loot+1;if not r.itemID then c.unknownIDs=c.unknownIDs+1 end end end
 return c
end
